-- REVIEW ONLY. One CREATE OR REPLACE statement. Execute as SQL script in DBeaver.
USE auxiliares;
DELIMITER $$
CREATE OR REPLACE TRIGGER `TRG_FB_CONSULTAS_VERSION` BEFORE UPDATE ON `FB_CIU_CONSULTAS_WEB` FOR EACH ROW
BEGIN
IF NOT (BINARY OLD.`ID_CONSULTA` <=> BINARY NEW.`ID_CONSULTA`) OR NOT (BINARY OLD.`ID_PERSONA` <=> BINARY NEW.`ID_PERSONA`) OR NOT (BINARY OLD.`PADCOD` <=> BINARY NEW.`PADCOD`) OR NOT (BINARY OLD.`PADRON` <=> BINARY NEW.`PADRON`) OR NOT (BINARY OLD.`LOCALIDAD_PADRON` <=> BINARY NEW.`LOCALIDAD_PADRON`) OR NOT (BINARY OLD.`USUARIO_CREADOR_ID` <=> BINARY NEW.`USUARIO_CREADOR_ID`) OR NOT (BINARY OLD.`FECHA_ALTA` <=> BINARY NEW.`FECHA_ALTA`) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_IDENTIDAD_INMUTABLE'; END IF;
IF NOT (BINARY OLD.`ID_CONSULTA` <=> BINARY NEW.`ID_CONSULTA`) OR NOT (BINARY OLD.`PADRON` <=> BINARY NEW.`PADRON`) OR NOT (BINARY OLD.`PADCOD` <=> BINARY NEW.`PADCOD`) OR NOT (BINARY OLD.`LOCALIDAD_PADRON` <=> BINARY NEW.`LOCALIDAD_PADRON`) OR NOT (BINARY OLD.`NOMBRE_COMPLETO` <=> BINARY NEW.`NOMBRE_COMPLETO`) OR NOT (BINARY OLD.`REL_COD` <=> BINARY NEW.`REL_COD`) OR NOT (BINARY OLD.`TIPO_DOCUMENTO` <=> BINARY NEW.`TIPO_DOCUMENTO`) OR NOT (BINARY OLD.`DOCUMENTO` <=> BINARY NEW.`DOCUMENTO`) OR NOT (BINARY OLD.`DOMICILIO_CALLE` <=> BINARY NEW.`DOMICILIO_CALLE`) OR NOT (BINARY OLD.`DOMICILIO_PUERTA` <=> BINARY NEW.`DOMICILIO_PUERTA`) OR NOT (BINARY OLD.`DOMICILIO_BLOCK` <=> BINARY NEW.`DOMICILIO_BLOCK`) OR NOT (BINARY OLD.`DOMICILIO_APTO` <=> BINARY NEW.`DOMICILIO_APTO`) OR NOT (BINARY OLD.`DOMICILIO_LOCALIDAD` <=> BINARY NEW.`DOMICILIO_LOCALIDAD`) OR NOT (BINARY OLD.`DOMICILIO_DEPARTAMENTO` <=> BINARY NEW.`DOMICILIO_DEPARTAMENTO`) OR NOT (BINARY OLD.`TELEFONO_1` <=> BINARY NEW.`TELEFONO_1`) OR NOT (BINARY OLD.`TIPO_TELEFONO_1` <=> BINARY NEW.`TIPO_TELEFONO_1`) OR NOT (BINARY OLD.`TELEFONO_2` <=> BINARY NEW.`TELEFONO_2`) OR NOT (BINARY OLD.`TIPO_TELEFONO_2` <=> BINARY NEW.`TIPO_TELEFONO_2`) OR NOT (BINARY OLD.`TELEFONO_3` <=> BINARY NEW.`TELEFONO_3`) OR NOT (BINARY OLD.`TIPO_TELEFONO_3` <=> BINARY NEW.`TIPO_TELEFONO_3`) OR NOT (BINARY OLD.`TELEFONO_4` <=> BINARY NEW.`TELEFONO_4`) OR NOT (BINARY OLD.`TIPO_TELEFONO_4` <=> BINARY NEW.`TIPO_TELEFONO_4`) OR NOT (BINARY OLD.`TELEFONO_5` <=> BINARY NEW.`TELEFONO_5`) OR NOT (BINARY OLD.`TIPO_TELEFONO_5` <=> BINARY NEW.`TIPO_TELEFONO_5`) OR NOT (BINARY OLD.`MAIL_1` <=> BINARY NEW.`MAIL_1`) OR NOT (BINARY OLD.`MAIL_2` <=> BINARY NEW.`MAIL_2`) OR NOT (BINARY OLD.`MAIL_3` <=> BINARY NEW.`MAIL_3`) OR NOT (BINARY OLD.`MAIL_4` <=> BINARY NEW.`MAIL_4`) OR NOT (BINARY OLD.`MAIL_5` <=> BINARY NEW.`MAIL_5`) OR NOT (BINARY OLD.`TIPO_CONSULTA` <=> BINARY NEW.`TIPO_CONSULTA`) OR NOT (BINARY OLD.`DESCRIPCION` <=> BINARY NEW.`DESCRIPCION`) OR NOT (BINARY OLD.`USUARIO_CREADOR_ID` <=> BINARY NEW.`USUARIO_CREADOR_ID`) OR NOT (BINARY OLD.`FECHA_ALTA` <=> BINARY NEW.`FECHA_ALTA`) OR NOT (BINARY OLD.`ID_PERSONA` <=> BINARY NEW.`ID_PERSONA`) OR NOT (BINARY OLD.`ID_PERSONA_CP` <=> BINARY NEW.`ID_PERSONA_CP`) OR NOT (BINARY OLD.`CONCOD` <=> BINARY NEW.`CONCOD`) OR NOT (BINARY OLD.`RELACION_DECLARADA` <=> BINARY NEW.`RELACION_DECLARADA`) OR NOT (BINARY OLD.`DOMICILIO_DECLARADO_JSON` <=> BINARY NEW.`DOMICILIO_DECLARADO_JSON`) OR NOT (BINARY OLD.`REFERENCIAS_CP_JSON` <=> BINARY NEW.`REFERENCIAS_CP_JSON`) THEN
 IF NEW.USUARIO_MODIFICADOR_ID IS NULL OR CHAR_LENGTH(TRIM(NEW.USUARIO_MODIFICADOR_ID))=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_ACTOR_REQUERIDO'; END IF;
 SET NEW.VERSION=OLD.VERSION+1; SET NEW.FECHA_MODIFICACION=UTC_TIMESTAMP(6);
 ELSE SET NEW.VERSION=OLD.VERSION; SET NEW.FECHA_MODIFICACION=OLD.FECHA_MODIFICACION; SET NEW.USUARIO_MODIFICADOR_ID=OLD.USUARIO_MODIFICADOR_ID; END IF;
END$$
DELIMITER ;
